const events = $input.all();
let message = "";

const now = new Date();

const getStartDate = (event) => {
  if (event.json.start?.dateTime) {
    return new Date(event.json.start.dateTime);
  }

  if (event.json.start?.date) {
    return new Date(`${event.json.start.date}T00:00:00+07:00`);
  }

  return new Date(8640000000000000);
};

const getEndDate = (event, start) => {
  if (event.json.end?.dateTime) {
    return new Date(event.json.end.dateTime);
  }

  if (event.json.end?.date) {
    return new Date(`${event.json.end.date}T23:59:59+07:00`);
  }

  return new Date(start.getTime() + 60 * 60 * 1000);
};

const cleanText = (text) => {
  if (!text) return "";

  return String(text)
    .replace(/<[^>]*>/g, "")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/\s+/g, " ")
    .trim();
};

const formatDate = (date) => {
  return date.toLocaleDateString("id-ID", {
    weekday: "long",
    day: "2-digit",
    month: "long",
    year: "numeric",
    timeZone: "Asia/Jakarta",
  });
};

const formatTime = (date) => {
  return date.toLocaleTimeString("id-ID", {
    hour: "2-digit",
    minute: "2-digit",
    timeZone: "Asia/Jakarta",
  });
};

const parseTitle = (summary) => {
  const title = cleanText(summary);

  const result = {
    rawTitle: title,
    room: "",
    course: title,
    code: "",
    examType: "",
  };

  // Contoh: [F3.11] Pancasila (PCS) - UAS
  const match = title.match(/^\[(.*?)\]\s*(.*?)\s*(?:\((.*?)\))?\s*-\s*(.*)$/);

  if (match) {
    result.room = cleanText(match[1]);
    result.course = cleanText(match[2]);
    result.code = cleanText(match[3]);
    result.examType = cleanText(match[4]);
  }

  return result;
};

const parseDescription = (description) => {
  const desc = cleanText(description);

  const result = {
    prodi: "",
    kelas: "",
    jumlahMahasiswa: "",
    ruang: "",
    dosen: "",
  };

  // Split berdasarkan koma yang diikuti label berikutnya
  // Aman untuk nama dosen yang punya koma gelar, misal S.Fil., M.Phil.
  const labels = ["Prodi", "Kelas", "Jumlah Mahasiswa", "Ruang", "Dosen"];

  labels.forEach((label, index) => {
    const nextLabels = labels.slice(index + 1).join("|");

    const regex = nextLabels
      ? new RegExp(`${label}:\\s*(.*?)(?=,\\s*(?:${nextLabels}):|$)`, "i")
      : new RegExp(`${label}:\\s*(.*)$`, "i");

    const match = desc.match(regex);

    if (match) {
      const value = cleanText(match[1]).replace(/,$/, "");

      if (label === "Prodi") result.prodi = value;
      if (label === "Kelas") result.kelas = value;
      if (label === "Jumlah Mahasiswa") result.jumlahMahasiswa = value;
      if (label === "Ruang") result.ruang = value;
      if (label === "Dosen") result.dosen = value;
    }
  });

  return result;
};

const getStatus = (start, end) => {
  if (now >= start && now <= end) {
    return " 🔥 *NOW*";
  }

  if (now > end) {
    return " ✅ *DONE*";
  }

  const diffMinutes = Math.floor((start - now) / 60000);
  const diffHours = Math.floor(diffMinutes / 60);
  const diffDays = Math.floor(diffHours / 24);

  if (diffMinutes <= 60) {
    return ` 🚀 *NEXT* ⏳ (${diffMinutes} menit lagi)`;
  }

  if (diffHours < 24) {
    return ` ⏳ (${diffHours} jam lagi)`;
  }

  return ` ⏳ (${diffDays} hari lagi)`;
};

if (events.length === 0) {
  message = "Kosong coi... belum ada jadwal UAS yang kebaca 😴";
} else {
  events.sort((a, b) => getStartDate(a) - getStartDate(b));

  message = "🗓️ *RECAP JADWAL UAS*\n";
  message += "📌 Hari ini sampai 12 Juni\n\n";

  let currentDateLabel = "";

  events.forEach((event) => {
    const start = getStartDate(event);
    const end = getEndDate(event, start);

    const dateLabel = formatDate(start);

    if (dateLabel !== currentDateLabel) {
      currentDateLabel = dateLabel;
      message += `📅 *${dateLabel}*\n`;
    }

    const titleData = parseTitle(event.json.summary);
    const descData = parseDescription(event.json.description);

    const room = titleData.room || descData.ruang || "-";
    const course = titleData.course || event.json.summary || "Tanpa judul";
    const code = titleData.code ? ` (${titleData.code})` : "";
    const examType = titleData.examType ? ` - ${titleData.examType}` : "";

    const timeText = event.json.start?.dateTime
      ? `${formatTime(start)} - ${formatTime(end)} WIB`
      : "Seharian";

    const status = getStatus(start, end);

    message += `• *${course}${code}${examType}*${status}\n`;
    message += `  ⏰ ${timeText}\n`;
    message += `  🏫 Kelas: ${descData.kelas || "-"}\n`;
    message += `  📍 Ruang: ${room}\n`;

    if (descData.jumlahMahasiswa) {
      message += `  👥 ${descData.jumlahMahasiswa} mahasiswa\n`;
    }

    if (descData.dosen) {
      message += `  👨‍🏫 ${descData.dosen}\n`;
    }

    message += "------------------------------\n";
  });
}

return [{ message }];

